const i = $input.first().json;
const accion = String(i.accion ?? '');
const user_id = Number(i.user_id);
const titulo = String(i.titulo ?? '').trim();
const notas = String(i.notas ?? '').trim();
const vence = String(i.vence ?? '').trim();
const tarea_id = Number(i.tarea_id) || 0;

// Si la validacion falla se corre esta consulta inofensiva y el error viaja a Formato.
let sql = "select '[]'::json as filas, 0 as coincidencias";
let params = [];
let error = null;

if (!Number.isInteger(user_id) || user_id <= 0) {
  error = 'user_id inválido';
} else if (accion === 'crear') {
  if (!titulo) error = 'Falta el título de la tarea';
  else if (titulo.length > 200) error = 'El título es demasiado largo (máx. 200)';
  else if (vence && (!/^\d{4}-\d{2}-\d{2}$/.test(vence) || isNaN(Date.parse(vence)))) error = 'La fecha debe tener formato AAAA-MM-DD';
  else {
    sql = "with n as (insert into tasks (user_id, titulo, notas, vence) values ($1, $2, nullif($3, ''), nullif($4, '')::date) returning id, titulo, vence) select coalesce(json_agg(n), '[]'::json) as filas, 1 as coincidencias from n";
    params = [user_id, titulo, notas, vence];
  }
} else if (accion === 'listar') {
  sql = "select coalesce(json_agg(t), '[]'::json) as filas, 0 as coincidencias from (select id, titulo, vence, notas from tasks where user_id = $1 and estado = 'pendiente' order by vence nulls last, id limit 30) t";
  params = [user_id];
} else if (accion === 'completar') {
  if (!tarea_id && !titulo) error = 'Indica el id o parte del título de la tarea';
  else {
    // Solo completa si hay exactamente una coincidencia.
    sql = "with c as (select id from tasks where user_id = $1 and estado = 'pendiente' and (($2::bigint > 0 and id = $2::bigint) or ($2::bigint = 0 and titulo ilike '%' || $3 || '%'))), u as (update tasks set estado = 'hecha', completed_at = now() where id in (select id from c) and (select count(*) from c) = 1 returning id, titulo) select coalesce((select json_agg(u) from u), '[]'::json) as filas, (select count(*) from c)::int as coincidencias";
    params = [user_id, tarea_id, titulo];
  }
} else {
  error = 'Acción desconocida: ' + accion;
}

return [{ json: { accion, entrada: { titulo, notas, vence, tarea_id }, sql, params, error } }];

const p = $('Preparar').first().json;
const r = $input.first().json;
const filas = Array.isArray(r.filas) ? r.filas : [];
let ok = !p.error;
let error = p.error;
let resumen = '';

if (ok && p.accion === 'crear') {
  resumen = `Tarea creada: "${filas[0].titulo}"` + (filas[0].vence ? ` para el ${filas[0].vence}` : '');
} else if (ok && p.accion === 'listar') {
  resumen = filas.length ? `${filas.length} tarea(s) pendiente(s)` : 'No hay tareas pendientes';
} else if (ok && p.accion === 'completar') {
  if (filas.length === 1) resumen = `Tarea completada: "${filas[0].titulo}"`;
  else {
    ok = false;
    error = r.coincidencias === 0
      ? 'No encontré una tarea pendiente que coincida'
      : `Hay ${r.coincidencias} tareas que coinciden; pide al usuario que precise cuál`;
  }
}
if (!ok) resumen = error;

return [{ json: {
  respuesta: { ok, data: filas, resumen, error: ok ? null : error },
  log: [JSON.stringify(p.entrada), JSON.stringify([`tareas.${p.accion}`]), resumen, ok ? null : error],
} }];
